parameters.jsCode:
// Pick the FIRST FREE 1-hour slot in HR's Google Calendar.
// Input = output of "Check HR Calendar" (raw freeBusy response, or a list of {start,end}).
// Rules: start tomorrow, skip Fri/Sat (Egypt weekend), slots start 11:00-15:00, look 14 days ahead.
const busy = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.calendars) {
    for (const cal of Object.values(j.calendars)) {
      if (cal.errors && cal.errors.length) {
        throw new Error('Cannot read HR calendar: ' + JSON.stringify(cal.errors));
      }
      (cal.busy || []).forEach(b => busy.push(b));
    }
  } else if (j.start && j.end) {
    busy.push({ start: j.start, end: j.end });
  }
}
const ranges = busy.map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));

const startHours = [11, 12, 13, 14, 15];
let day = $now.plus({ days: 1 }).startOf('day');

for (let i = 0; i < 14; i++, day = day.plus({ days: 1 })) {
  if ([5, 6].includes(day.weekday)) continue; // Fri, Sat
  for (const h of startHours) {
    const s = day.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
    const e = s.plus({ hours: 1 });
    const clash = ranges.some(r => s < r.e && e > r.s);
    if (!clash) {
      return [{
        json: {
          start: s.toISO(),
          end: e.toISO(),
          pretty: s.toFormat("cccc, dd LLL yyyy 'at' hh:mm a") + ' (Cairo time)'
        }
      }];
    }
  }
}
throw new Error('No free interview slot in the next 14 days in HR calendar');

